75	@RestController
76	@CrossOrigin(exposedHeaders = "errors, content-type")
77	@RequestMapping("/api")
78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    /**
81	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
82	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
83	     */
84	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
85	
86	    /**
87	     * Domains known to hand out disposable/throwaway mailboxes. An owner whose email domain is on
88	     * this blocklist is rejected: such addresses cannot be relied on for contacting the owner.
89	     */
90	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
91	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
92	
93	    /** Dedicated audit logger; create side-effects are recorded here so they can be observed independently. */
94	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
95	
96	    /** Dedicated notification logger; the welcome notification enqueued on a successful create is emitted here. */
97	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
98	
99	    /**
100	     * Source of the monotonically increasing {@code seq} stamped on each {@link OwnerCreatedEvent}.
101	     * Incremented once per successful create so the emitted events form a gap-free, strictly increasing
102	     * sequence across all creates handled by this application instance.
103	     */
104	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
105	
106	    /** Request header carrying the client-supplied idempotency key for owner creation. */
107	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
108	
109	    /**
110	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that create originally
111	     * produced for it. A repeated create carrying a key found here returns that same owner instead of
112	     * creating a duplicate, making owner creation idempotent with respect to the key.
113	     */
114	    private final Map<String, Integer> ownersByIdempotencyKey = new ConcurrentHashMap<>();
115	
116	    private final ClinicService clinicService;
117	
118	    private final OwnerMapper ownerMapper;
119	
120	    private final PetMapper petMapper;
121	
122	    private final VisitMapper visitMapper;
123	
124	    /** Serializes the structured {@link OwnerCreatedEvent} to JSON for the {@code AUDIT} logger. */
125	    private final ObjectMapper objectMapper;
