139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
142	        Collection<Owner> owners;
143	        if (lastName != null) {
144	            owners = this.clinicService.findOwnerByLastName(lastName);
145	        } else {
146	            owners = this.clinicService.findAllOwners();
147	        }
148	        if (owners.isEmpty()) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        List<OwnerDto> ownerDtos = owners.stream()
152	            .map(this::toOwnerDtoWithBulkWarning)
153	            .toList();
154	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
155	    }
