157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        return new ResponseEntity<>(toOwnerDtoWithBulkWarning(owner), HttpStatus.OK);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
170	        String idempotencyKey = currentIdempotencyKey();
171	        if (idempotencyKey != null) {
172	            Integer existingId = this.ownersByIdempotencyKey.get(idempotencyKey);
173	            if (existingId != null) {
174	                Owner existing = this.clinicService.findOwnerById(existingId);
175	                if (existing != null) {
176	                    return new ResponseEntity<>(toOwnerDtoWithBulkWarning(existing), HttpStatus.OK);
177	                }
178	            }
179	        }
180	        List<String> missingFields = new ArrayList<>();
181	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
182	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
183	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
184	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
185	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
186	        boolean hasStructuredAddress = !normalizedAddressLine1.isEmpty();
187	        String normalizedAddress = hasStructuredAddress
188	            ? composeAddress(normalizedAddressLine1, normalizedAddressLine2)
189	            : normalizedFlatAddress;
190	        requireNonBlank(missingFields, "address", normalizedAddress);
191	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
192	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
193	        if (!missingFields.isEmpty()) {
194	            throw new MissingRequiredFieldsException(missingFields);
195	        }
196	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
197	        validateRegistrationDate(ownerFieldsDto.getRegistrationDate());
198	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
199	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
200	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
201	        requireDailyLimitNotReached(registrationDate);
202	        requireCityBelowCapacity(ownerFieldsDto.getCity());
203	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
204	        ownerFieldsDto.setTelephone(normalizedTelephone);
205	        if (ownerFieldsDto.getEmail() != null) {
206	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
207	        }
208	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
209	        HttpHeaders headers = new HttpHeaders();
210	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
211	        owner.setAddress(normalizedAddress);
212	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
213	        owner.setAddressLine2(hasStructuredAddress && !normalizedAddressLine2.isEmpty()
214	            ? normalizedAddressLine2 : null);
215	        owner.setRegistrationDate(registrationDate);
216	        owner.setMemberId(buildMemberId(owner, normalizedTelephone));
217	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
218	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
219	        requireUniqueIdentity(owner);
220	        markPossibleDuplicate(owner, sharesHousehold);
221	        this.clinicService.saveOwner(owner);
222	        if (idempotencyKey != null) {
223	            this.ownersByIdempotencyKey.put(idempotencyKey, owner.getId());
224	        }
225	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
226	        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
227	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
228	            ownerDto.getMembershipLevel());
229	        OwnerCreatedEvent event = OwnerCreatedEvent.forCreatedOwner(
230	            OWNER_CREATED_SEQUENCE.incrementAndGet(), owner, ownerDto.getMembershipLevel());
231	        AUDIT.info(this.objectMapper.writeValueAsString(event));
232	        NOTIFY.info("Welcome notification enqueued for owner id={} memberId={}",
233	            owner.getId(), owner.getMemberId());
234	        headers.setLocation(UriComponentsBuilder.newInstance()
235	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
236	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
237	    }
238	
239	    /**
240	     * Returns the {@code Idempotency-Key} header of the request in progress, or {@code null} when the
241	     * header is absent, blank, or there is no active servlet request. The generated {@link OwnersApi}
242	     * signature carries no header parameter, so it is read from the current request context.
243	     */
244	    private static String currentIdempotencyKey() {
245	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
246	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
247	            if (key != null && !key.isBlank()) {
248	                return key;
249	            }
250	        }
251	        return null;
252	    }
