347	    /**
348	     * Builds the owner's unified {@code memberId} as {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION}
349	     * is the region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'})
350	     * via {@link OwnerMapper#toRegion}; {@code FY} is the 2-digit fiscal year of the owner's
351	     * business-day-adjusted {@code registrationDate}; {@code HASH8} is the first 8 upper-case hex
352	     * characters of the SHA-256 digest of {@code normalizedTelephone + lastName}; and {@code CHK} is a
353	     * single Luhn check digit over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW261A2B3C4D9}).
354	     *
355	     * <p>When the computed id collides with an existing owner's {@code memberId}, it is de-duplicated by
356	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique (e.g.
357	     * {@code NSW261A2B3C4D9-2}); the de-duplicated id is returned. Absent a collision the base id is
358	     * returned unchanged.
359	     *
360	     * @param owner the owner being created, with its region-determining postcode/city and
361	     *              registrationDate populated
362	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
363	     * @return the (de-duplicated) member id for the owner being created
364	     */
365	    private String buildMemberId(Owner owner, String normalizedTelephone) {
366	        String region = ownerMapper.toRegion(owner);
367	        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
368	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
369	        String core = region + fy + hash8;
370	        String baseId = core + luhnCheckDigit(core);
371	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
372	            .map(Owner::getMemberId)
373	            .filter(java.util.Objects::nonNull)
374	            .collect(java.util.stream.Collectors.toSet());
375	        if (!existingIds.contains(baseId)) {
376	            return baseId;
377	        }
378	        int n = 2;
379	        while (existingIds.contains(baseId + "-" + n)) {
380	            n++;
381	        }
382	        return baseId + "-" + n;
383	    }
384	
385	    /**
386	     * Computes a single Luhn check digit (0-9) over the decimal digits contained in {@code value};
387	     * non-digit characters are ignored. Used to append the {@code CHK} segment to a member id's
388	     * {@code <REGION><FY><HASH8>} core.
389	     */
390	    private static int luhnCheckDigit(String value) {
391	        int sum = 0;
392	        boolean dbl = true;
393	        for (int i = value.length() - 1; i >= 0; i--) {
394	            char c = value.charAt(i);
395	            if (c < '0' || c > '9') {
396	                continue;
397	            }
398	            int d = c - '0';
399	            if (dbl) {
400	                d *= 2;
401	                if (d > 9) {
402	                    d -= 9;
403	                }
404	            }
405	            sum += d;
406	            dbl = !dbl;
407	        }
408	        return (10 - (sum % 10)) % 10;
409	    }
410	
411	    /**
412	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
413	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
414	     */
415	    private static String sha256Hex8(String value) {
416	        try {
417	            byte[] digest = MessageDigest.getInstance("SHA-256")
418	                .digest(value.getBytes(StandardCharsets.UTF_8));
419	            StringBuilder sb = new StringBuilder();
420	            for (byte b : digest) {
421	                sb.append(String.format("%02X", b));
422	            }
423	            return sb.substring(0, 8);
424	        }
425	        catch (NoSuchAlgorithmException e) {
426	            throw new IllegalStateException("SHA-256 not available", e);
427	        }
428	    }
