456	    /**
457	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
458	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
459	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
460	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
461	     * {@code "+61412345678"}.
462	     *
463	     * @param telephone the raw telephone value from the request
464	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
465	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
466	     */
467	    private static String normalizeTelephone(String telephone) {
468	        String e164 = toE164(telephone);
469	        if (e164 == null) {
470	            throw new InvalidFieldValueException("telephone",
471	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
472	        }
473	        return e164;
474	    }
475	
476	    /**
477	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
478	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
479	     * owners' stored numbers when detecting duplicates.
480	     */
481	    private static String toE164(String telephone) {
482	        if (telephone == null) {
483	            return null;
484	        }
485	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
486	        String digits;
487	        if (cleaned.startsWith("+")) {
488	            digits = cleaned.substring(1);
489	        } else {
490	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
491	            digits = "61" + national;
492	        }
493	        if (!digits.matches("[0-9]{8,15}")) {
494	            return null;
495	        }
496	        if (!hasValidNationalLength(digits)) {
497	            return null;
498	        }
499	        return "+" + digits;
500	    }
501	
502	    /**
503	     * Checks the national-number length against the country code for the country codes that pin one.
504	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
505	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
506	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
507	     */
508	    private static boolean hasValidNationalLength(String digits) {
509	        if (digits.startsWith("61")) {
510	            return digits.length() - 2 == 9;
511	        }
512	        if (digits.startsWith("1")) {
513	            return digits.length() - 1 == 10;
514	        }
515	        return true;
516	    }
