519	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
520	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
521	     *
522	     * @param email the raw email value from the request (already known to be non-null)
523	     * @return the lower-cased email to be stored and returned
524	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
525	     */
526	    private static String normalizeEmail(String email) {
527	        String trimmed = email.trim();
528	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
529	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
530	        }
531	        String canonical = trimmed.toLowerCase(Locale.ROOT);
532	        String domain = canonical.substring(canonical.indexOf('@') + 1);
533	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
534	            throw new InvalidFieldValueException("email", "Email must not use a disposable-domain address");
535	        }
536	        return canonical;
