576	    /**
577	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
578	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
579	     * owner's registration date, otherwise {@code false}.
580	     *
581	     * @param owner the owner to map
582	     * @return the owner DTO with its bulk-signup warning flag populated
583	     */
584	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
585	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
586	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
587	        ownerDto.setCapacityWarning(approachingCityCapacity(owner.getCity()));
588	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
589	        ownerDto.setMembershipPoints(points);
590	        ownerDto.setMembershipLevel(capMembershipLevel(owner, OwnerMapper.membershipLevelFor(points)));
591	        return ownerDto;
