594	    /**
595	     * Caps the owner's {@code membershipLevel} so it cannot exceed one above the current maximum
596	     * membership level among the other members of its household (existing owners carrying the same
597	     * {@code householdId}, excluding the owner itself and any soft-deleted owner). When the household
598	     * has no other member — including when the owner has no {@code householdId} — no cap applies and
599	     * {@code level} is returned unchanged. Each household member's level is its own base level (points
600	     * mapped to a level for its real household size), so the cap does not depend on other capped
601	     * values.
602	     *
603	     * @param owner the owner whose membership level is being computed
604	     * @param level the owner's uncapped membership level derived from its membership points
605	     * @return the membership level capped at {@code maxHouseholdMemberLevel + 1}, or {@code level}
606	     *         when the owner has no other household member
607	     */
608	    private int capMembershipLevel(Owner owner, int level) {
609	        String householdId = owner.getHouseholdId();
610	        if (householdId == null) {
611	            return level;
612	        }
613	        Integer maxMemberLevel = this.clinicService.findAllOwners().stream()
614	            .filter(existing -> !isDeleted(existing))
615	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
616	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
617	            .map(this::membershipLevelForOwner)
618	            .max(Integer::compareTo)
619	            .orElse(null);
620	        if (maxMemberLevel == null) {
621	            return level;
622	        }
623	        return Math.min(level, maxMemberLevel + 1);
624	    }
