626	    /**
627	     * Computes an existing household member's membership level: its membership points for its real
628	     * household size mapped to the numeric level. Used to establish the household's current maximum
629	     * level when capping a new owner's level.
630	     */
631	    private int membershipLevelForOwner(Owner owner) {
632	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
633	        return OwnerMapper.membershipLevelFor(points);
634	    }
