678	    /**
679	     * Fixed list of public holidays. A registration date landing on one of these dates is rolled
680	     * forward, just like a weekend, until it reaches a non-holiday business day.
681	     */
682	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
683	        LocalDate.of(2026, 1, 1),
684	        LocalDate.of(2026, 1, 26),
685	        LocalDate.of(2026, 4, 25),
686	        LocalDate.of(2026, 12, 25),
687	        LocalDate.of(2026, 12, 28));
688	
689	    /**
690	     * Rolls {@code date} forward to a business day: while it falls on a Saturday, Sunday, or a listed
691	     * public holiday it advances one day at a time until it reaches a non-holiday weekday. Applied to
692	     * the effective registration date (whether supplied in the request or defaulted to the server date)
693	     * so a weekend or holiday registration is recorded on the next business day, and every value derived
694	     * from the registration date uses the adjusted date.
695	     *
696	     * @param date the effective registration date (supplied or defaulted), never {@code null}
697	     * @return the same date, or the next non-holiday business day when {@code date} is a weekend or holiday
698	     */
699	    private static LocalDate toBusinessDay(LocalDate date) {
700	        LocalDate adjusted = date;
701	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
702	            adjusted = adjusted.plusDays(1);
703	        }
704	        return adjusted;
705	    }
