707	    /** Whether {@code date} falls on a Saturday or Sunday. */
708	    private static boolean isWeekend(LocalDate date) {
709	        DayOfWeek day = date.getDayOfWeek();
710	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
711	    }
