713	    /** Matches a well-formed postcode: exactly four decimal digits. */
714	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
715	
716	    /**
717	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
718	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
719	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
720	     * present here and accepts any well-formed postcode.
721	     */
722	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
723	        "NSW", new int[] {2000, 2099},
724	        "VIC", new int[] {3000, 3099},
725	        "QLD", new int[] {4000, 4099});
726	
727	    /**
728	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
729	     * optional, so the request contract stays backward-compatible). When present it must be exactly
730	     * four digits and, for a city whose region is known, fall within that region's inclusive range
731	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
732	     * postcode. A malformed or out-of-range value is rejected with a 400.
733	     *
734	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
735	     * @param city the owner's city, used to look up the region whose range constrains the postcode
736	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
737	     */
738	    private void validatePostcode(String postcode, String city) {
739	        if (postcode == null) {
740	            return;
741	        }
742	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
743	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
744	        }
745	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
746	        int[] range = REGION_POSTCODES.get(region);
747	        if (range == null) {
748	            return;
749	        }
750	        int value = Integer.parseInt(postcode);
751	        if (value < range[0] || value > range[1]) {
752	            throw new InvalidFieldValueException("postcode",
753	                "Postcode must be valid for the city's region " + region);
754	        }
755	    }
