838	     * has the same {@code soundex(lastName)} and the same {@code postcode} as this owner but a
839	     * <em>different</em> {@code identityKey}, the owner is a possible duplicate: {@code possibleDuplicate}
840	     * is set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest such
841	     * owner by id when more than one matches). Otherwise both are cleared. A declared household member
842	     * ({@code sharesHousehold} true) is never flagged: it is a deliberate member, not a suspected
843	     * duplicate. An owner with no {@code postcode} never matches, since the soft match is keyed on it.
844	     *
845	     * @param owner the incoming owner, with its telephone, email and postcode populated
846	     * @param sharesHousehold whether the request opted in as a declared household member
847	     */
848	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
849	        owner.setPossibleDuplicate(false);
850	        owner.setPossibleDuplicateOf(null);
851	        if (sharesHousehold) {
852	            return;
853	        }
854	        String postcode = owner.getPostcode();
855	        if (postcode == null || postcode.isBlank()) {
856	            return;
857	        }
858	        String soundex = OwnerIdentity.soundex(owner.getLastName());
859	        String identityKey = ownerMapper.toIdentityKey(owner);
860	        this.clinicService.findAllOwners().stream()
861	            .filter(existing -> !isDeleted(existing))
862	            .filter(existing -> postcode.equals(existing.getPostcode()))
863	            .filter(existing -> soundex.equals(OwnerIdentity.soundex(existing.getLastName())))
864	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
865	            .min(java.util.Comparator.comparing(Owner::getId))
866	            .ifPresent(match -> {
867	                owner.setPossibleDuplicate(true);
868	                owner.setPossibleDuplicateOf(match.getId());
869	            });
870	    }
871	
872	    /**
873	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
874	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
875	     * comparisons are case-insensitive.
876	     */
877	    private static String normalizeForHousehold(String value) {
878	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
879	    }
880	
881	    /**
882	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
883	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
884	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
885	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
886	     * value normalizes to the empty string, so the required-field check rejects an address that is
887	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
888	     *
889	     * @param address the raw address value from the request (may be {@code null})
890	     * @return the normalized address, or the empty string when blank after normalization
891	     */
892	    private static String normalizeAddress(String address) {
893	        if (address == null) {
894	            return "";
895	        }
896	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
897	        if (collapsed.isEmpty()) {
898	            return "";
899	        }
900	        String[] tokens = collapsed.split(" ");
901	        StringBuilder sb = new StringBuilder();
902	        for (String token : tokens) {
903	            String expanded = switch (token) {
904	                case "ST" -> "STREET";
905	                case "RD" -> "ROAD";
906	                case "AVE" -> "AVENUE";
907	                default -> token;
908	            };
909	            if (sb.length() > 0) {
910	                sb.append(' ');
911	            }
912	            sb.append(expanded);
913	        }
914	        return sb.toString();
915	    }
916	
917	    /**
918	     * Composes the stored/returned {@code address} from the normalized structured lines: the
919	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
920	     * appended when {@code addressLine2} is present (non-empty). Both arguments are already
921	     * normalized via {@link #normalizeAddress(String)}.
922	     *
923	     * @param normalizedAddressLine1 the normalized first address line (non-empty)
924	     * @param normalizedAddressLine2 the normalized second address line, or the empty string when absent
925	     * @return the composed address string
926	     */
927	    private static String composeAddress(String normalizedAddressLine1, String normalizedAddressLine2) {
928	        if (normalizedAddressLine2.isEmpty()) {
929	            return normalizedAddressLine1;
930	        }
931	        return normalizedAddressLine1 + " " + normalizedAddressLine2;
932	    }
933	
934	    /**
935	     * Derives the stable household identifier for an owner from its last name and postcode as the
936	     * upper-cased first 12 hex characters of the SHA-256 digest of
937	     * {@code normalizedLastName + '|' + postcode}, where the last name is normalized (trimmed,
938	     * internal whitespace collapsed, lower-cased) so casing and spacing do not affect it. Because the
939	     * identifier is a deterministic function of the normalized last name and postcode, owners that
940	     * share a last name and postcode share the identifier automatically — no back-fill or opt-in is
941	     * required. Returns {@code null} when no postcode is present, since the household is keyed on the
942	     * postcode and there is then nothing to key on.
943	     *
944	     * @param lastName the owner's last name (already validated non-blank)
945	     * @param postcode the owner's postcode (a validated 4-digit value, or {@code null} when absent)
946	     * @return the 12-hex-character household identifier, or {@code null} when no postcode is present
947	     */
948	    private static String householdIdFor(String lastName, String postcode) {
949	        if (postcode == null || postcode.isBlank()) {
950	            return null;
951	        }
952	        String normalizedLastName = normalizeForHousehold(lastName);
953	        try {
954	            byte[] digest = MessageDigest.getInstance("SHA-256")
955	                .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
956	            StringBuilder sb = new StringBuilder();
957	            for (byte b : digest) {
958	                sb.append(String.format("%02X", b));
959	            }
960	            return sb.substring(0, 12);
961	        }
962	        catch (NoSuchAlgorithmException e) {
963	            throw new IllegalStateException("SHA-256 not available", e);
964	        }
965	    }
966	}
